CREATE TABLE IF NOT EXISTS clients (id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'privato', phone TEXT DEFAULT '', email TEXT DEFAULT '', address TEXT DEFAULT '', city TEXT DEFAULT '', zip TEXT DEFAULT '', vat_number TEXT DEFAULT '', tax_code TEXT DEFAULT '', notes TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vehicles (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, category TEXT NOT NULL DEFAULT 'auto', brand TEXT DEFAULT '', model TEXT DEFAULT '', plate TEXT DEFAULT '', year TEXT DEFAULT '', notes TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quotes (id TEXT PRIMARY KEY, number TEXT NOT NULL UNIQUE, client_id TEXT NOT NULL REFERENCES clients(id), vehicle_id TEXT REFERENCES vehicles(id) ON DELETE SET NULL, mode TEXT NOT NULL DEFAULT 'rapido', category TEXT NOT NULL DEFAULT 'auto', brand TEXT DEFAULT '', model TEXT DEFAULT '', subject TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'bozza', items_json TEXT NOT NULL DEFAULT '[]', discount_pct REAL NOT NULL DEFAULT 0, vat_pct REAL NOT NULL DEFAULT 22, delivery TEXT DEFAULT '', payment TEXT DEFAULT '', validity_days INTEGER NOT NULL DEFAULT 30, notes TEXT DEFAULT '', internal_notes TEXT DEFAULT '', template TEXT NOT NULL DEFAULT 'premium', issued_at TEXT NOT NULL, accepted_at TEXT, completed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_quotes_client ON quotes(client_id);
CREATE INDEX IF NOT EXISTS idx_vehicles_client ON vehicles(client_id);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS counters (year INTEGER PRIMARY KEY, last_number INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, quote_id TEXT NOT NULL REFERENCES quotes(id) ON DELETE CASCADE, filename TEXT NOT NULL, mime TEXT NOT NULL, object_key TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
